[standards/technology/nodejs/STD-TEC-NODE-001-security.md#41-validation-library-mandate]

### 4.1 Validation Library Mandate

All request inputs — path parameters, query strings, request bodies, and headers — **must** be validated using **`zod`** (preferred) or **`joi`**. Raw `req.body` must never be used without schema validation. Validation must occur in middleware or at the controller boundary, before the value reaches any service or repository layer.

```typescript
import { z } from 'zod';
import { Request, Response, NextFunction } from 'express';

const CreateMemberSchema = z
  .object({
    memberId: z.string().uuid(),
    dateOfBirth: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    planCode: z.string().min(1).max(20),
  })
  .strict();

type CreateMemberRequest = z.infer<typeof CreateMemberSchema>;

function validateCreateMember(req: Request, res: Response, next: NextFunction): void {
  const result = CreateMemberSchema.safeParse(req.body);
  if (!result.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: result.error.flatten().fieldErrors,
    });
    return;
  }
  req.validatedBody = result.data;
  next();
}
```

